ring=[('r',17,c) for c in (23,26,29,32,35)]+[('c',r,35) for r in range(20,42,3)]+[('r',44,c) for c in (35,32,29,26,23)]+[('c',r,23) for r in range(41,19,-3)]
ring=[(c,r) for _,r,c in ring]
rows={26:[(c,26) for c in range(17,45,3)],35:[(c,35) for c in range(17,45,3)]}
def mv(p,m):
    if m[0]=='ring':
        if p in ring: return ring[(ring.index(p)+m[1])%26]
        return p
    L=rows[m[0]]
    if p in L: return L[(L.index(p)+m[1])%10]
    return p
from collections import deque
moves=[('ring',-1),('ring',1),(26,-1),(26,1),(35,-1),(35,1)]
start=((26,17),(23,44));goal={(35,26),(35,35)}
prev={start:None};q=deque([start])
while q:
    s=q.popleft()
    if set(s)==goal:break
    for m in moves:
        n=tuple(mv(p,m) for p in s)
        if n not in prev: prev[n]=(s,m);q.append(n)
path=[]
while prev[s]: s,m=prev[s];path.append(m)
path=path[::-1];print(len(path),path)
